effect.shader:
const int TAPS = 16;
void main(){
  vec2 baseUv = acScreenNorm;
  vec2 centre = vec2(centerX, centerY);
  vec4 acc = vec4(0.0);
  for (int i = 0; i < TAPS; i++){
    float t = (float(i) / float(TAPS - 1) - 0.5) * amount * mixAmt;
    vec2 p = centre + (baseUv - centre) * (1.0 + t);
    acc += texture2DCv(inputImg.texture, p);
  }
  acc /= float(TAPS);
  float a = max(acc.a, 1e-4);
  vec2 radial = (baseUv - centre) * amount * chroma * mixAmt;
  float r = texture2DCv(inputImg.texture, baseUv + radial).r / max(texture2DCv(inputImg.texture, baseUv + radial).a, 1e-4);
  float g = acc.rgb.g / a;
  float b = texture2DCv(inputImg.texture, baseUv - radial).b / max(texture2DCv(inputImg.texture, baseUv - radial).a, 1e-4);
  gl_FragColor = vec4(clamp(vec3(r, g, b), 0.0, 1.0) * a, a);
}
